// A rate period is a contiguous weekday-only or weekend-only band, so a stay's
// nights often span more than one (e.g. a Sat-Mon stay needs a weekend night
// from one segment and a weekday night from the next). Group the requested
// nights by whichever segment's `available` list currently has each one, then
// touch every segment the stay needs:
for (var segment : nightsByRateSegment.entrySet()) {
    session.operate(hotels, key)
        .removeByValue("rooms." + roomId + ".rates[" + segment.rateIndex + "].available", segment.nights)
        .append("rooms." + roomId + ".rates[" + segment.rateIndex + "].booked", reservation)
        .execute();
}
